# 06 tables 1-4 (docx)
suppressMessages({library(data.table);library(officer);library(flextable)})
B<-readRDS("R.rds"); O<-readRDS("M.rds"); FONT<-"Times New Roman"; doc<-read_docx()
tp<-function(sz=12,b=FALSE) fp_text(font.family=FONT,font.size=sz,bold=b)
BR<-function() doc<<-body_add_break(doc)
## ---- tables
set_flextable_defaults(font.family=FONT,font.size=8.5,padding=2,line_spacing=1)
ft<-function(d,w=6.7){x<-flextable(as.data.frame(d)); x<-theme_booktabs(x); x<-bold(x,part="header"); x<-align(x,j=-1,align="center",part="all"); x<-autofit(x); fit_to_width(x,w)}
TB<-function(d,cap,foot){BR(); doc<<-body_add_fpar(doc,fpar(ftext(cap,tp(11,TRUE)),fp_p=fp_par(line_spacing=1.15,padding.bottom=4))); doc<<-body_add_flextable(doc,ft(d)); doc<<-body_add_fpar(doc,fpar(ftext(foot,tp(9)),fp_p=fp_par(line_spacing=1.15,padding.top=4)))}
c3<-function(x) sprintf("%.2f (%.2f–%.2f)",x[1],x[2],x[3]); p3<-function(p) if(p<0.001) "<0.001" else sprintf("%.3f",p)
cp<-function(x) paste0(c3(x),"; ",ifelse(x[4]<0.001,"P < 0.001",paste0("P = ",p3(x[4]))))
pv1<-function(p) ifelse(p<0.001,"P < 0.001",paste0("P = ",p3(p)))
t1<-copy(O$T1[["MIMIC-IV"]]); setnames(t1,"Characteristic","Characteristic")
TB(t1,"Table 1 Baseline characteristics and outcomes in MIMIC-IV by early postoperative driving pressure","Values are median (interquartile range) or number (percentage). P values are from the Wilcoxon rank-sum test or the χ² test. Ventilator variables are medians of values recorded 0–6 h after ICU admission; laboratory values are those closest to ICU admission; the PaO₂/FiO₂ ratio is the first value within 6 h. Tidal volume per kg of predicted body weight was available for 2,596 patients with recorded height. Glucose was missing in 85.5% of patients and is not shown or used. The severity score is the first-day Sequential Organ Failure Assessment score without its respiratory and neurological components. CABG, coronary artery bypass grafting; COPD, chronic obstructive pulmonary disease; DP, driving pressure; ICU, intensive care unit; PBW, predicted body weight; PEEP, positive end-expiratory pressure")
cn<-O$cnt; G<-function(dbx,g){r<-cn[cn[["db"]]==dbx]; if(g==0) sprintf("%d/%s (%.1f)",r$pmv0,format(r$n0,big.mark=","),100*r$pmv0/r$n0) else sprintf("%d/%s (%.1f)",r$pmv1,format(r$n1,big.mark=","),100*r$pmv1/r$n1)}
ar<-function(db,i) {a<-O$ar[[db]]; sprintf("%.1f (%.1f–%.1f)",100*a[1,i],100*a[2,i],100*a[3,i])}
row<-function(lab,f) data.table(Analysis=lab,`MIMIC-IV`=f("MIMIC-IV"),`eICU-CRD`=f("eICU-CRD"))
T2<-rbind(row("Ventilation >24 h, n/N (%)",function(d) ""),row("   DP <15 cmH₂O",function(d) G(d,0)),row("   DP ≥15 cmH₂O",function(d) G(d,1)),
 row("DP ≥15 vs <15 cmH₂O, OR (95% CI)",function(d) ""),row("   Model 1 (unadjusted)",function(d) cp(B[[d]]$crude)),row("   Model 2",function(d) cp(B[[d]]$m2)),row("   Model 3",function(d) cp(B[[d]]$m3)),
 row("Standardised risk from model 3, % (95% CI)",function(d) ""),row("   DP <15 cmH₂O",function(d) ar(d,1)),row("   DP ≥15 cmH₂O",function(d) ar(d,2)),row("   Risk difference, percentage points",function(d) ar(d,3)),
 row("DP per 1 cmH₂O, OR (95% CI), model 3",function(d) cp(B[[d]]$cont)),
 row("DP categories, OR (95% CI), model 3",function(d) ""),row("   <10 cmH₂O",function(d) "1 (reference)"),row("   10–14 cmH₂O",function(d) cp(B[[d]]$cat[1,])),row("   ≥15 cmH₂O",function(d) cp(B[[d]]$cat[2,])),row("   P for trend",function(d) pv1(B[[d]]$trend[4])),
 row("Restricted cubic spline (4 knots), P overall / P nonlinear",function(d) paste0(pv1(B[[d]]$rcs[1])," / ",pv1(B[[d]]$rcs[2]))),
 row("Added value of DP ≥15 cmH₂O to model 3",function(d) ""),row("   Pooled Wald test",function(d) pv1(B[[d]]$inc[1])),row("   Median AUC without → with DP (DeLong test)",function(d) sprintf("%.3f → %.3f; %s",B[[d]]$inc[2],B[[d]]$inc[3],pv1(B[[d]]$inc[4]))))
TB(T2,"Table 2 Early postoperative driving pressure and ventilation beyond 24 h (primary outcome)","Model 1 is unadjusted. Model 2 is adjusted for age, sex, weight, urgent or emergency admission, type of surgery, heart failure, COPD, chronic kidney disease, diabetes mellitus, atrial fibrillation, myocardial infarction, peripheral vascular disease, hypertension, liver disease, obesity and pulmonary hypertension. Model 3 is further adjusted for severity of illness (SOFA score without respiratory and neurological components in MIMIC-IV; APACHE IV in eICU-CRD), vasopressor and inotrope use, haemoglobin, white cell count, platelet count, heart rate, mean arterial pressure, PEEP and log PaO₂/FiO₂ ratio, plus creatinine and lactate (MIMIC-IV) or glucose (eICU-CRD); covariates missing in more than 20% of patients were not used. Estimates were pooled across 20 imputed datasets with Rubin's rules; AUC values and DeLong P values are medians across imputed datasets. Standardised risks were obtained by g-computation with 100 bootstrap samples per imputed dataset. In eICU-CRD, ventilation >24 h was defined as ventilator settings charted 25–30 h after ICU admission. AUC, area under the receiver operating characteristic curve; CI, confidence interval; DP, driving pressure; OR, odds ratio")
nn<-function(a,b,n0,n1) sprintf("%d/%s (%.1f) vs %d/%s (%.1f)",b,format(n1,big.mark=","),100*b/n1,a,format(n0,big.mark=","),100*a/n0)
m<-cn[cn$db=="MIMIC-IV"]; e<-cn[cn$db=="eICU-CRD"]; BM<-B[["MIMIC-IV"]]; BE<-B[["eICU-CRD"]]
dd<-function(z) sprintf("%.2f (%.2f to %.2f); %s",z[1],z[2],z[3],pv1(z[4]))
ev<-function(a,b,n0,n1) sprintf("%d (%.1f%%) vs %d (%.1f%%)",b,100*b/n1,a,100*a/n0)
T3<-data.table(Outcome=c("Reintubation within 7 days","   Events, DP ≥15 vs <15","   Propensity score-adjusted, OR","   Model 2, OR","Extubation by day 28, Fine–Gray model 3, SHR","Duration of first ventilation episode, model 3, ratio of geometric means","Ventilator-free days to day 28, model 3, difference (days)","ICU stay among 28-day survivors, model 3, ratio of geometric means","28-day mortality","   Events, DP ≥15 vs <15","   Propensity score-adjusted, OR","In-hospital mortality","   Events, DP ≥15 vs <15","   Propensity score-adjusted, OR","1-year mortality","   Events, DP ≥15 vs <15","   Propensity score-adjusted Cox model, HR"),
 `MIMIC-IV`=c("",ev(m$re0,m$re1,m$n0,m$n1),cp(BM$s_re),cp(BM$s_reM),cp(BM$s_ext),cp(BM$s_mvh),dd(BM$s_vfd),cp(BM$s_los),"",ev(m$d280,m$d281,m$n0,m$n1),cp(BM$s_d28),"",ev(m$hd0,m$hd1,m$n0,m$n1),cp(BM$s_hd),"",ev(m$y10,m$y11,m$n0,m$n1),cp(BM$s_y1)),
 `eICU-CRD`=c("","Not available","Not available","Not available","Not available","Not available","Not available",cp(BE$s_los),"",ev(e$d280,e$d281,e$n0,e$n1),cp(BE$s_d28),"",ev(e$hd0,e$hd1,e$n0,e$n1),cp(BE$s_hd),"","Not available","Not available"))
TB(T3,"Table 3 Secondary outcomes by early postoperative driving pressure (≥15 vs <15 cmH₂O)","Estimates were pooled across 20 imputed datasets. Model covariates are as in Table 2. Propensity score adjustment (logit of the propensity score for driving pressure ≥15 cmH₂O, estimated from the model 3 covariates) was used for outcomes with few events. Time to extubation was analysed with death before extubation as a competing event; an SHR below 1 indicates slower extubation. eICU-CRD does not record extubation times, reintubation or deaths after hospital discharge. CI, confidence interval; DP, driving pressure; HR, hazard ratio; ICU, intensive care unit; OR, odds ratio; SHR, subdistribution hazard ratio")
S<-function(nm) function(d){x<-B[[d]]$S[[nm]]; if(is.null(x)) "Not applicable" else paste0(cp(x),"; n = ",format(x[5],big.mark=","))}
SM<-function(nm) function(d) if(d=="eICU-CRD") "Not available" else S(nm)(d)
T4<-rbind(row("Main analysis (model 3, multiple imputation)",function(d) paste0(cp(B[[d]]$m3),"; n = ",format(B[[d]]$n,big.mark=","))),
 row("Confounding control",function(d) ""),row("   Inverse probability of treatment weighting",function(d) cp(B[[d]]$iptw)),row("   Overlap weighting",function(d) cp(B[[d]]$ow)),row("   Doubly robust (IPTW + model 3)",function(d) cp(B[[d]]$dr)),
 row("   Propensity score matching 1:1",function(d) paste0(cp(B[[d]]$psm),"; ",B[[d]]$psm[5]," pairs")),row("   Maximum SMD before → after matching",function(d) sprintf("%.2f → %.2f",B[[d]]$smd[1],B[[d]]$smd[2])),
 row("   E-value (point estimate)",function(d) sprintf("%.2f",B[[d]]$ev)),
 row("Model stability (events per parameter)",function(d) ""),row("   Firth penalised logistic regression",S("firth")),row("   Parsimonious model (8 covariates)",S("pars")),row("   Adjustment for propensity score",S("ps_adj")),
 row("   Hospital-clustered standard errors",function(d) if(d=="eICU-CRD") paste0(cp(O$cl),"; ",O$cl[5]," hospitals") else "Not applicable (single centre)"),
 row("Ventilator mode and outcome definition",function(d) ""),row("   DP from controlled-mode measurements only",SM("mode_ctl")),row("   Excluding patients with any spontaneous-mode measurement",SM("mode_nospont")),row("   Outcome defined as in eICU-CRD (settings charted 25–30 h)",SM("harm")),row("   Inverse probability of selection weighting",SM("selw")),
 row("Alternative exposure definitions",function(d) ""),row("   Median DP 0–24 h ≥15 cmH₂O",S("dp24")),row("   First recorded DP ≥15 cmH₂O",S("dpfirst")),row("   Threshold 14 cmH₂O",S("t14")),row("   Threshold 16 cmH₂O",S("t16")),
 row("Restricted populations",function(d) ""),row("   Without ARDS or pneumonia",S("noards")),row("   Without COPD",S("nocopd")),row("   PaO₂/FiO₂ ≥300 mmHg",S("pf300")),row("   Isolated CABG",S("cabg")),row("   Elective surgery",S("elective")),row("   ≥2 DP measurements within 0–6 h",S("ndp2")),row("   No vasopressor or inotrope",S("novaso")),
 row("Alternative adjustment and missing data",function(d) ""),row("   Additionally adjusted for tidal volume per kg PBW",S("vtk")),row("   PaO₂/FiO₂ ratio removed from model 3",S("nopf")),row("   Median imputation",S("median_imp")),row("   Complete-case analysis",S("cc")),
 row("Alternative outcomes",function(d) ""),row("   Ventilation >48 h",SM("p48")),row("   Ventilation >24 h or reintubation within 7 days",SM("comp")))
TB(T4,"Table 4 Confounding control and sensitivity analyses for ventilation beyond 24 h","Odds ratios (95% CI) compare driving pressure ≥15 with <15 cmH₂O and are adjusted as model 3 unless stated otherwise; estimates were pooled across 20 imputed datasets except for median imputation and complete-case analysis. Propensity scores were estimated from all model 3 covariates; inverse probability weights were truncated at the 99th percentile; matching used a caliper of 0.2 standard deviations of the logit of the propensity score; weighted and matched estimates have robust standard errors. The parsimonious model included age, sex, weight, type of surgery, severity of illness, PEEP and PaO₂/FiO₂ ratio. Controlled modes were volume or pressure assist-control modes charted within 1 h of the measurement. Selection weights were derived from age, sex, type of surgery and urgency among all patients ventilated on ICU arrival. Tidal volume per kg PBW was available only for patients with recorded height. ARDS, acute respiratory distress syndrome; CABG, coronary artery bypass grafting; CI, confidence interval; COPD, chronic obstructive pulmonary disease; DP, driving pressure; IPTW, inverse probability of treatment weighting; PBW, predicted body weight; SMD, standardised mean difference")
print(doc,target="Tables.docx")
